<?php
namespace App\Http\Controllers;
use App\Models\{SeoActivity,SeoBacklinkActivity,SeoCampaign,SeoMonthlyCycle,SeoOnPageOptimization,SeoPerformanceRecord,SeoReport,SeoTechnicalIssue};
use Illuminate\Http\Request; use Illuminate\Support\Facades\Storage; use Illuminate\Validation\Rule;

class SeoOperationsController extends Controller {
 public function dashboard(SeoCampaign $campaign){$this->authorize('view',$campaign);if($this->isClient())return redirect()->route('seo.workspace',[$campaign,'tab'=>'reports']);$latest=$campaign->keywords()->with('latestRanking')->get();return view('seo.operations.dashboard',['campaign'=>$campaign,'k'=>$latest->count(),'top10'=>$latest->filter(fn($keyword)=>$keyword->latestRanking?->rank_position&&$keyword->latestRanking->rank_position<=10)->count(),'latest'=>$latest]);}
 public function workspace(SeoCampaign $campaign,Request $request){$this->authorize('view',$campaign);$isClient=$this->isClient();$tab=$isClient?'reports':$request->get('tab','activities');$reports=$campaign->reports()->latest('period_end');if($isClient)$reports->where('status','published');$latestPeriod=$campaign->performanceRecords()->max('period_end');$current=$latestPeriod?$campaign->performanceRecords()->where('period_end',$latestPeriod)->pluck('metric_value','metric_key'):collect();$keywords=$campaign->keywords()->with('latestRanking')->get();return view('seo.operations.workspace',['campaign'=>$campaign,'tab'=>$tab,'isClient'=>$isClient,'team'=>$campaign->members()->with('user')->whereNull('unassigned_at')->get(),'cycles'=>$campaign->cycles()->latest('month')->get(),'activities'=>$campaign->activities()->with('assignee')->latest()->get(),'technical'=>SeoTechnicalIssue::where('seo_campaign_id',$campaign->id)->with('assignee')->latest()->get(),'backlinks'=>SeoBacklinkActivity::where('seo_campaign_id',$campaign->id)->latest()->get(),'onpage'=>SeoOnPageOptimization::where('seo_campaign_id',$campaign->id)->latest('optimized_on')->get(),'performance'=>$campaign->performanceRecords()->latest('period_end')->get(),'reports'=>$reports->get(),'clientOverview'=>['baseline'=>$campaign->baseline?->metrics()->pluck('metric_value','metric_key')??collect(),'current'=>$current,'period'=>$latestPeriod,'keywords'=>$keywords->count(),'top10'=>$keywords->filter(fn($keyword)=>$keyword->latestRanking?->rank_position&&$keyword->latestRanking->rank_position<=10)->count(),'completedActivities'=>$campaign->activities()->whereIn('status',['approved','completed'])->count()]]);}
 public function addCycle(Request $r,SeoCampaign $campaign){$this->authorize('manage',$campaign);$d=$r->validate(['month'=>'required|date','objectives'=>'nullable|string|max:5000']);$campaign->cycles()->updateOrCreate(['month'=>date('Y-m-01',strtotime($d['month']))],$d+['created_by'=>auth()->id()]);return back()->with('success','Monthly SEO cycle saved.');}
 public function addActivity(Request $r,SeoCampaign $campaign){$this->authorize('contribute',$campaign);$d=$r->validate(['seo_monthly_cycle_id'=>'nullable|exists:seo_monthly_cycles,id','category'=>['required',Rule::in(['on_page','technical','content','off_page','local','analytics','reporting','other'])],'title'=>'required|string|max:255','target_url'=>'nullable|url|max:2048','description'=>'nullable|string|max:5000','assigned_to'=>'nullable|exists:users,id','start_date'=>'nullable|date','deadline'=>'nullable|date','priority'=>['required',Rule::in(['high','medium','low'])]]);$this->ensureCycle($campaign,$d['seo_monthly_cycle_id']??null);$this->ensureMember($campaign,$d['assigned_to']??null);$campaign->activities()->create($d);return back()->with('success','SEO activity assigned.');}
 public function updateActivity(Request $r,SeoCampaign $campaign,SeoActivity $activity){$this->authorize('contribute',$campaign);abort_unless($activity->seo_campaign_id===$campaign->id,404);$this->ensureOwner($campaign,$activity->assigned_to);abort_if(in_array($activity->status,['approved','completed']),422,'Approved activities are locked.');$d=$r->validate(['status'=>['required',Rule::in(['todo','in_progress','submitted'])],'work_notes'=>'nullable|string|max:5000','evidence_url'=>'nullable|url|max:2048']);$activity->update($d);return back()->with('success',$d['status']==='submitted'?'Work submitted for manager review.':'Activity progress saved.');}
 public function reviewActivity(Request $r,SeoCampaign $campaign,SeoActivity $activity){$this->authorize('manage',$campaign);abort_unless($activity->seo_campaign_id===$campaign->id&&$activity->status==='submitted',422,'Only submitted activities can be reviewed.');$d=$r->validate(['decision'=>['required',Rule::in(['approved','changes_required'])],'feedback'=>'nullable|string|max:5000']);$activity->update(['status'=>$d['decision'],'reviewed_by'=>auth()->id(),'reviewed_at'=>now(),'review_feedback'=>$d['feedback']??null,'completed_at'=>$d['decision']==='approved'?now():null]);return back()->with('success',$d['decision']==='approved'?'Activity approved.':'Changes requested from executive.');}
 public function addTechnical(Request $r,SeoCampaign $campaign){$this->authorize('contribute',$campaign);$d=$r->validate(['title'=>'required|string|max:255','issue_type'=>['required',Rule::in(['crawl','indexing','sitemap','redirect','broken_link','canonical','speed','mobile','schema','core_web_vitals','other'])],'affected_url'=>'nullable|url|max:2048','description'=>'nullable|string|max:5000','severity'=>['required',Rule::in(['critical','high','medium','low'])],'assigned_to'=>'nullable|exists:users,id']);$this->ensureMember($campaign,$d['assigned_to']??null);SeoTechnicalIssue::create($d+['seo_campaign_id'=>$campaign->id,'status'=>empty($d['assigned_to'])?'identified':'assigned']);return back()->with('success','Technical issue logged.');}
 public function updateTechnical(Request $r,SeoCampaign $campaign,SeoTechnicalIssue $technicalIssue){$this->authorize('contribute',$campaign);abort_unless($technicalIssue->seo_campaign_id===$campaign->id,404);$this->ensureOwner($campaign,$technicalIssue->assigned_to);$d=$r->validate(['status'=>['required',Rule::in(['identified','assigned','fix_in_progress','implemented','verification_pending','verified_closed','reopened'])],'resolution_notes'=>'nullable|string|max:5000','evidence_url'=>'nullable|url|max:2048']);if($d['status']==='verified_closed')$this->authorize('manage',$campaign);$technicalIssue->update($d+($d['status']==='verified_closed'?['verified_at'=>now(),'verified_by'=>auth()->id()]:[]));return back()->with('success','Technical issue progress updated.');}
 public function addOnPage(Request $r,SeoCampaign $campaign){$this->authorize('contribute',$campaign);$d=$r->validate(['seo_activity_id'=>'nullable|exists:seo_activities,id','page_url'=>'required|url|max:2048','target_keyword'=>'nullable|string|max:255','old_meta_title'=>'nullable|string|max:1000','new_meta_title'=>'nullable|string|max:1000','old_meta_description'=>'nullable|string|max:2000','new_meta_description'=>'nullable|string|max:2000','h1_changes'=>'nullable|string|max:3000','content_changes'=>'nullable|string|max:5000','alt_tag_changes'=>'nullable|string|max:3000','internal_link_changes'=>'nullable|string|max:3000','evidence_url'=>'nullable|url|max:2048','optimized_on'=>'required|date']);if(!empty($d['seo_activity_id']))abort_unless($campaign->activities()->whereKey($d['seo_activity_id'])->exists(),422,'Selected activity does not belong to this campaign.');SeoOnPageOptimization::create($d+['seo_campaign_id'=>$campaign->id,'created_by'=>auth()->id()]);return back()->with('success','On-page optimisation log saved.');}
 public function addBacklink(Request $r,SeoCampaign $campaign){$this->authorize('contribute',$campaign);$d=$r->validate(['activity_type'=>'required|string|max:255','target_website'=>'nullable|url|max:2048','target_url'=>'nullable|url|max:2048','published_url'=>'nullable|url|max:2048','anchor_text'=>'nullable|string|max:255','link_type'=>['required',Rule::in(['dofollow','nofollow','sponsored','ugc','unknown'])],'verification_status'=>['required',Rule::in(['submitted','published','verified','lost','rejected'])],'submitted_on'=>'nullable|date','live_on'=>'nullable|date','remarks'=>'nullable|string|max:5000']);SeoBacklinkActivity::create($d+['seo_campaign_id'=>$campaign->id,'assigned_to'=>auth()->id()]);return back()->with('success','Off-page activity recorded.');}
 public function addPerformance(Request $r,SeoCampaign $campaign){$this->authorize('contribute',$campaign);$d=$r->validate(['period_start'=>'required|date','period_end'=>'required|date|after_or_equal:period_start','source'=>['required',Rule::in(['manual','ga4','search_console','import'])],'metric_key'=>'required|string|max:100','metric_value'=>'nullable|numeric']);SeoPerformanceRecord::updateOrCreate(['seo_campaign_id'=>$campaign->id,'period_start'=>$d['period_start'],'period_end'=>$d['period_end'],'source'=>$d['source'],'metric_key'=>$d['metric_key']],$d+['recorded_by'=>auth()->id(),'recorded_at'=>now()]);return back()->with('success','Performance metric saved.');}
 public function createReport(Request $r,SeoCampaign $campaign){$this->authorize('contribute',$campaign);$d=$r->validate(['title'=>'required|string|max:255','period_start'=>'required|date','period_end'=>'required|date|after_or_equal:period_start','observations'=>'nullable|string|max:10000','attachments'=>'nullable|array|max:10','attachments.*'=>'file|mimes:xlsx,xls,psd|max:51200']);$files=$r->file('attachments',[]);unset($d['attachments']);$report=$campaign->reports()->create($d+['prepared_by'=>auth()->id(),'snapshot'=>$this->snapshot($campaign,$d['period_start'],$d['period_end'])]);$attachments=[];foreach($files as $file){$path=$file->store("seo-reports/{$campaign->id}/{$report->id}",'public');$attachments[]=['name'=>$file->getClientOriginalName(),'path'=>$path,'type'=>$file->getClientOriginalExtension(),'size'=>$file->getSize()];}$report->update(['attachments'=>$attachments]);return back()->with('success','SEO report draft created with '.count($attachments).' attachment(s).');}
 public function submitReport(SeoCampaign $campaign,SeoReport $report){$this->authorize('contribute',$campaign);abort_unless($report->seo_campaign_id===$campaign->id&&in_array($report->status,['draft','changes_required']),422,'Only draft reports can be submitted.');$report->update(['status'=>'submitted']);return back()->with('success','Report submitted for review.');}
 public function reviewReport(Request $r,SeoCampaign $campaign,SeoReport $report){$this->authorize('manage',$campaign);abort_unless($report->seo_campaign_id===$campaign->id,404);$d=$r->validate(['decision'=>['required',Rule::in(['approved','changes_required','published'])],'feedback'=>'nullable|string|max:5000']);abort_if($d['decision']==='approved'&&$report->status!=='submitted',422,'Only submitted reports can be approved.');abort_if($d['decision']==='published'&&$report->status!=='approved',422,'Approve the report before publishing it.');$report->update(['status'=>$d['decision'],'reviewed_by'=>auth()->id(),'reviewed_at'=>now(),'review_feedback'=>$d['feedback']??null]);return back()->with('success',ucfirst($d['decision']).' report saved.');}
 private function snapshot(SeoCampaign $campaign,string $start,string $end):array{$baseline=$campaign->baseline?->metrics()->pluck('metric_value','metric_key')??collect();$metrics=$campaign->performanceRecords()->whereBetween('period_end',[$start,$end])->orderBy('period_end')->get()->groupBy('metric_key')->map(fn($rows)=>$rows->last()->metric_value);$ranks=$campaign->keywords()->with('rankings')->get()->map(function($keyword){$rows=$keyword->rankings->sortBy('checked_on')->values();$current=$rows->last()?->rank_position;$previous=$rows->count()>1?$rows->slice(-2,1)->first()?->rank_position:null;return ['keyword'=>$keyword->keyword,'current'=>$current,'change'=>!is_null($current)&&!is_null($previous)?$previous-$current:null];});return ['generated_at'=>now()->toIso8601String(),'metrics'=>$metrics,'baseline'=>$baseline,'metric_change'=>$metrics->map(fn($v,$k)=>is_numeric($v)&&is_numeric($baseline->get($k))?$v-$baseline->get($k):null),'keywords_tracked'=>$ranks->count(),'top_10_keywords'=>$ranks->filter(fn($row)=>$row['current']&&$row['current']<=10)->count(),'gainers'=>$ranks->filter(fn($row)=>($row['change']??0)>0)->sortByDesc('change')->take(5)->values(),'decliners'=>$ranks->filter(fn($row)=>($row['change']??0)<0)->sortBy('change')->take(5)->values(),'activities_completed'=>$campaign->activities()->whereIn('status',['approved','completed'])->whereBetween('completed_at',[$start,$end.' 23:59:59'])->count(),'technical_closed'=>SeoTechnicalIssue::where('seo_campaign_id',$campaign->id)->where('status','verified_closed')->whereBetween('verified_at',[$start,$end.' 23:59:59'])->count(),'backlinks_verified'=>SeoBacklinkActivity::where('seo_campaign_id',$campaign->id)->where('verification_status','verified')->whereBetween('live_on',[$start,$end])->count()];}
 private function ensureMember(SeoCampaign $campaign,$userId):void{if($userId)abort_unless($campaign->members()->where('user_id',$userId)->whereNull('unassigned_at')->exists(),422,'Assignee must be an active campaign member.');}
 private function ensureCycle(SeoCampaign $campaign,$cycleId):void{if($cycleId)abort_unless($campaign->cycles()->whereKey($cycleId)->exists(),422,'Selected month does not belong to this campaign.');}
 private function ensureOwner(SeoCampaign $campaign,$assignedTo):void{if(!auth()->user()->can('manage',$campaign)&&$assignedTo&&(int)$assignedTo!==(int)auth()->id())abort(403,'Only assigned executive or manager can update this work.');}
 private function isClient():bool{return in_array(strtolower((string)(auth()->user()?->getRawOriginal('role')??'')),['client','customer'],true);}
}
